create extension if not exists "pgcrypto";
create table public.users(id uuid primary key references auth.users(id) on delete cascade, objective text, preferred_categories text[], created_at timestamptz default now());
create table public.categories(id uuid primary key default gen_random_uuid(), name text unique not null, slug text unique not null);
create table public.shops(id uuid primary key default gen_random_uuid(), external_id text unique, name text not null, category_id uuid references public.categories, rating numeric, created_at timestamptz default now());
create table public.products(id uuid primary key default gen_random_uuid(), external_id text unique, shop_id uuid references public.shops, category_id uuid references public.categories, name text not null, price numeric(12,2), commission numeric(5,2), created_at timestamptz default now());
create table public.creators(id uuid primary key default gen_random_uuid(), external_id text unique, name text not null, username text, followers bigint, created_at timestamptz default now());
create table public.videos(id uuid primary key default gen_random_uuid(), external_id text unique, creator_id uuid references public.creators, product_id uuid references public.products, url text, posted_at timestamptz);
create table public.product_metrics(id bigint generated always as identity primary key, product_id uuid not null references public.products on delete cascade, recorded_at timestamptz not null default now(), sales_count bigint, sales_24h bigint, sales_7d bigint, sales_30d bigint, gmv numeric(14,2), gmv_24h numeric(14,2), gmv_7d numeric(14,2), gmv_30d numeric(14,2), creator_count int, video_count int, views bigint, price numeric(12,2), commission numeric(5,2), rating numeric(3,2), review_count int);
create index product_metrics_history_idx on public.product_metrics(product_id, recorded_at desc);create index product_metrics_radar_idx on public.product_metrics(recorded_at desc, sales_24h desc, gmv_24h desc);
create table public.creator_metrics(id bigint generated always as identity primary key, creator_id uuid references public.creators on delete cascade, recorded_at timestamptz default now(), sales bigint, gmv numeric(14,2), views bigint, engagement numeric(8,4));
create table public.shop_metrics(id bigint generated always as identity primary key, shop_id uuid references public.shops on delete cascade, recorded_at timestamptz default now(), sales bigint, gmv numeric(14,2), active_products int);
create table public.video_metrics(id bigint generated always as identity primary key, video_id uuid references public.videos on delete cascade, recorded_at timestamptz default now(), views bigint, likes bigint, comments bigint, shares bigint, attributed_sales bigint, attributed_gmv numeric(14,2));
create table public.product_creators(product_id uuid references public.products on delete cascade, creator_id uuid references public.creators on delete cascade, first_seen_at timestamptz default now(), primary key(product_id,creator_id));
create table public.product_videos(product_id uuid references public.products on delete cascade, video_id uuid references public.videos on delete cascade, primary key(product_id,video_id));
create table public.opportunity_scores(id bigint generated always as identity primary key, product_id uuid references public.products on delete cascade, recorded_at timestamptz default now(), score int check(score between 0 and 100), saturation_score int check(saturation_score between 0 and 100), factors jsonb not null default '{}');
create table public.favorites(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, entity_type text check(entity_type in('product','creator','shop')), entity_id uuid not null, created_at timestamptz default now(), unique(user_id,entity_type,entity_id));
create table public.alerts(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, product_id uuid references public.products on delete cascade, kind text not null, title text not null, read_at timestamptz, created_at timestamptz default now());
create table public.watchlists(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users on delete cascade, name text not null, filters jsonb not null default '{}', created_at timestamptz default now());
alter table public.users enable row level security;alter table public.favorites enable row level security;alter table public.alerts enable row level security;alter table public.watchlists enable row level security;
create policy "users own profile" on public.users for all using(auth.uid()=id) with check(auth.uid()=id);create policy "users own favorites" on public.favorites for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "users own alerts" on public.alerts for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "users own watchlists" on public.watchlists for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
